const numeros = new Set(nums);
let mejor = 0;
for (const x of numeros) {
  if (/* x es el inicio de una secuencia */) {
    let actual = x;
    let largo = 1;
    while (/* existe el siguiente */) {
      actual++;
      largo++;
    }
    mejor = Math.max(mejor, largo);
  }
}
return mejor;
